// Turkish voice lines (class C). Native script, written from the beat in beats-*.js; never translated from English.
// Group: story-hoods-11-20. beatId -> [{ t, j (joke), spk (only when it differs from the beat) }]. No logic.
Object.assign(P.DLG.tr, {
  "H11i3b": [{ t: "Ninem kuzenlerimde. Garajın anahtarı bende. Burada biraz dinlenebiliriz." }],
  "H11b": [{ t: "Vazo üç yüz yıllıktı. Artık üç yüz parça.", ok: 1 }],
  "H11i1a": [{ t: "Haliç–Balat. Karanlıkta renkleri solan evler. Balkonlarda unutulmuş çamaşırlar." }],
  "H11i2a": [{ t: "Vitrindeki telefon kablolu. Şu an bana gelişmiş teknoloji gibi geliyor.", j: 1 }],
  "H11i3a": [{ t: "Fatma Nine'nin garajı. Kaan kapıda durdu. Tabelanın yarısı boyalı." }],
  "H11p1": [{ t: "Haliç ne kadar sessiz. Kendi adımlarımı duyuyorum." }],
  "H11p2": [{ t: "Bu evin rengini ninem seçmişti. Kaybolan herkes bizi buluyordu.", j: 1 }],
  "H11p3": [{ t: "Burada her şey ya eski ya pahalı. Ben ikisi de değilim, sadece terliyim.", j: 1, ok: 1 }],
  "H11p4": [{ t: "Şu tabela benim dükkân için. Açılışı biraz erteledik.", j: 1 }],
  "H12b": [{ t: "Yetişin! Tren gidiyor! İtmeyin! İtin! Kapı kapanıyor!", ok: 1 }],
  "H12i1a": [{ t: "Yenikapı. Metro tünelleri. Her yer karanlık, sadece el fenerinin ışığı var.", ok: 1 }],
  "H12i2a": [{ t: "Yerde bir telefon. Son mesaj, dünden: 'Eve gel. Seni bekliyoruz.'", ok: 1 }],
  "H12i3a": [{ t: "Merdivenden iniyorlar. Seslerini duyuyorum.", ok: 1 }],
  "H12p1": [{ t: "Fener ileriyi göstermiyor. Kaan, yanımdan ayrılma." }],
  "H12p2": [{ t: "Merdivenin başını tutalım abi. Arkana ben bakarım." }],
  "H12p3": [{ t: "Telefon titredi! Bir çubuk... sonra hiç. Umut verip kaçtı.", ok: 1 }],
  "H12p4": [{ t: "Ses burada çok yankılanıyor. Yavaş konuş abi." }],
  "H13b": [{ t: "Közler hazır! Sıra sende! Az pişmiş mi seversin, çok pişmiş mi?", ok: 1 }],
  "H13i1a": [{ t: "Samatya. Hava aydınlanıyor. Sahildeki battaniyeler gece nasıl kaldıysa öyle." }],
  "H13i2a": [{ t: "Kuzeydeki ormanda güvenli bölge kuruldu. Yayını tekrarlıyoruz: kuzeydeki ormanda..." }],
  "H13i3a": [{ t: "İstiklal'de de aynı anons vardı. Yollar kapalıyken oraya nasıl varacağız?" }],
  "H13p1": [{ t: "Piknik yarım kalmış. Tabaklar bile toplanmamış." }],
  "H13p2": [{ t: "Suya düşenler geri çıkamıyor. Kenardan dolaşalım abi." }],
  "H13p3": [{ t: "Paşa tıslıyor. Yine benden önce duydu bir şeyi." }],
  "H13p4": [{ t: "Mangal dumanı. Biri hâlâ ateş yakıyor. Kıyamet olmuş, mangal bırakılır mı?", ok: 1 }],
  "H14b": [{ t: "Bu kapının anahtarı bende! Yedeği yok! Kopyalatmam!", ok: 1 }],
  "H14i1a": [{ t: "Yedikule. Surların gölgesinde kilitli bir kapı." }],
  "H14i2a": [{ t: "Kapı kilitli. Bir de şu anahtar sesi nereden geliyor?" }],
  "H14i3a": [{ t: "Bekçi gölgede saklanıyor. Cebindeki anahtarların sesi her adımında yaklaşıyor." }],
  "H14p1": [{ t: "Sur yolu dar. Kenardan uzak duralım." }],
  "H14p2": [{ t: "Üç anahtar lazım abi. Birini bulduk mu diğerlerine bakarız." }],
  "H14p3": [{ t: "Çay bahçesinde oturacak yer yoktu. Şimdi kaçacak yer yok.", j: 1 }],
  "H14p4": [{ t: "Sarmaşıkların arkasında bir şey hışırdıyor. Rüzgâr değil. Rüzgâr hırıldamaz.", ok: 1 }],
  "H15b": [{ t: "Su bitmez, asit bitmez! Bahçe sulama saati!", ok: 1 }],
  "H15i1a": [{ t: "Kazlıçeşme. Serin sabah, yeşil çimler, dönen fıskiyeler. Fazla huzurlu.", ok: 1 }],
  "H15i2a": [{ t: "Bu kadar huzur kıllandırıyor. Filmlerde bu sahneden sonra hep biri ölür.", ok: 1 }],
  "H15i3a": [{ t: "Hortumdan çıkan şey su değil. Değdiği çimler kararıyor." }],
  "H15p1": [{ t: "Fıskiyeler her yeri ıslattı. Hortumcu gelince gözün üstünde olsun.", ok: 1 }],
  "H15p2": [{ t: "Suda kıvılcım var! Bekle Kaan, kuru yerden geçelim." }],
  "H15p3": [{ t: "İki yandan koşuyorlar. Abi, sırt sırta verelim!" }],
  "H15p4": [{ t: "Dizlerim sızlıyor ama deniz havası iyi geliyor. Yirmi yaşında emekli oldum.", ok: 1 }],
  "H16b": [{ t: "Vardiya bitmedi! Bidonları boşaltın! Mola yok, çay yok!", ok: 1 }],
  "H16i1a": [{ t: "Zeytinburnu. Boya atölyeleri. Renk renk bidonlar, hepsi ağızlarına kadar dolu.", ok: 1 }],
  "H16i2a": [{ t: "Usta hâlâ paydos vermemiş. Abi, sakın işe yarar görünme.", j: 1 }],
  "H16i3a": [{ t: "Bidonlar üst üste. Bir kıvılcım zincirleme hepsini patlatır.", ok: 1 }],
  "H16p1": [{ t: "Şu bidondan uzak dur. Patlarsa yanındakileri de götürür." }],
  "H16p2": [{ t: "Bant beni taşıyor abi. İndirme, sabahtan beri ilk rahatım.", j: 1 }],
  "H16p3": [{ t: "Boya kokusu başımı döndürdü. Kaan, sen hep mor muydun?", ok: 1 }],
  "H16p4": [{ t: "Usta kapının önünde. O çekilmeden çıkamayız abi." }],
  "H17b": [{ t: "Zil çaldı! Herkes sınıfa! Koridorda koşan velisini getirsin!", ok: 1 }],
  "H17i1a": [{ t: "Bakırköy Çarşısı. Pasajın sonunda eski lisemin kapısı." }],
  "H17i2a": [{ t: "Şu kapıdan her sabah geçerdim. Bugün girmek istemiyorum." }],
  "H17i3a": [{ t: "Okul müdürü megafonu açık bırakmış. Okul zili çalınca yine zombiler yığılır buraya.", ok: 1 }],
  "H17p1": [{ t: "Yürüyen merdiven durmuş. Basamaklardan çıkabilirim." }],
  "H17p2": [{ t: "Okul zili çalıyor. Her çalışta bir dalga geliyor. Lise travmam canlandı.", ok: 1 }],
  "H17p3": [{ t: "Yerde bir defter. Üstüne basmayayım." }],
  "H17p4": [{ t: "Her sabah şu kapıdan geçerdim. Hep geç kalırdım." }],
  "H18b": [{ t: "Bir kaşık daha? Bedava, bedava! Külahı tut! Tutamadın! Bir daha!", ok: 1 }],
  "H18i1a": [{ t: "Bakırköy sahili. Palmiyeler, bisiklet yolu ve bir dondurmacı arabası.", ok: 1 }],
  "H18i2a": [{ t: "Bu dondurmacıya çocukken borç takmıştım. \"Sonra verirsin,\" demişti. Veremedim." }],
  "H18i3a": [{ t: "Arabanın çanı çalıyor. Her çalışta zombiler akın ediyor.", ok: 1 }],
  "H18p1": [{ t: "Zil çalıyor. Sürü buraya dönmeden uzaklaşalım." }],
  "H18p2": [{ t: "Bisiklet yolundan geliyorlar. Ters yönden! Ölmüşler ama kural tanımıyorlar.", ok: 1 }],
  "H18p3": [{ t: "Sahil bomboş. Dalgalarla şu zil sesi kalmış." }],
  "H18p4": [{ t: "Çocukluğumun sahili. Aynı palmiyeler, aynı banklar. Sadece çok sessiz.", ok: 1 }],
  "H19b": [{ t: "Bu rıhtım benim! Herkesi bağlarım! Özel mülk, zombiler dahil!", ok: 1 }],
  "H19i1a": [{ t: "Ataköy Marina. Direklerin arasından evleri görüyorum. Bir kilometre kaldı." }],
  "H19i2a": [{ t: "Bundan sonrasını sen biliyorsun abi. Hangi sokak?" }],
  "H19i2b": [{ t: "Şuradan sağa. İki sokak sonra bizim apartman. Gel, az kaldı." }],
  "H19i3a": [{ t: "Yat sahibi. Rıhtımda halatlar sallanıyor. Zombiler uyanıyor.", ok: 1 }],
  "H19p1": [{ t: "Tahtalar sallanıyor. Yavaş geçelim, suya düşmeyelim." }],
  "H19p2": [{ t: "Halatlar ağ gibi. Zombiler takılıp kalıyor. Gizli balıkçılık yeteneğim ortaya çıktı.", ok: 1 }],
  "H19p3": [{ t: "Şu denizciyi bir an kaptana benzettim. Yürüyelim abi." }],
  "H19p4": [{ t: "Eve bir kilometre. Sen de gel Kaan. Biraz dinleniriz." }],
  "H20b": [{ t: "Ekmek... Evladım... Kapıyı aç..." }],
  "H20i1a": [{ t: "Ataköy. Bej binalar, mavi panjurlar, balkonlarda çamaşır ipleri. Ev.", ok: 1 }],
  "H20i2a": [{ t: "Fırın kokusu... Ahmet Abi her sabah buradaydı. 'Evladım, mont giy' derdi.", ok: 1 }],
  "H20i3a": [{ t: "Kapıcı kulübesinde biri var. Kapı aralık.", ok: 1 }],
  "H20p1": [{ t: "Kapıda ekmek sepeti var abi. Biri bırakıp gitmiş." }],
  "H20p2": [{ t: "Kapıcı kulübesinin anahtarı nerede? Ahmet Abi hep paspasın altına koyardı.", ok: 1 }],
  "H20p3": [{ t: "İplerin arasında biri var. Çarşafın arkasında kaldı, göremiyorum." }],
  "H20p4": [{ t: "Apartmandan ses geliyor. Dur Kaan, bir dinleyelim." }],
});
